def rollen_anlegen(apps, schema_editor):
    Group = apps.get_model("auth", "Group")
    Rolle = apps.get_model("konten", "Rolle")
    Tafel = apps.get_model("core", "TafelEinstellungen")
    Kunden = apps.get_model("kunden", "KundenEinstellungen")
    tafel = Tafel.objects.filter(pk=1).first()
    kunden = Kunden.objects.filter(pk=1).first()
    for name, (reihenfolge, rechte, feld, belehrung, fuehrerschein) in ROLLEN.items():
        rechte = list(rechte)
        if name == "Büro" and tafel and tafel.buero_verwaltet_mitarbeitende:
            rechte.append("mitarbeitende.verwalten")
        if name == "Ausgabe" and kunden and kunden.besondere_kategorie_fuer_ausgabe:
            rechte.append("kunden.besondere_kategorie")
        pflicht = getattr(tafel, feld) if tafel else Tafel._meta.get_field(feld).default
        gruppe, _ = Group.objects.get_or_create(name=name)
        Rolle.objects.get_or_create(
            gruppe=gruppe,
            defaults={
                "rechte": rechte,
                "reihenfolge": reihenfolge,
                "zwei_faktor_pflicht": pflicht,
                "braucht_belehrung": belehrung,
                "braucht_fuehrerschein": fuehrerschein,
            },
        )
    # Gruppen, die jemand selbst angelegt hat (z. B. über die Django-Verwaltung): ohne Rechte
    for gruppe in Group.objects.filter(rolle__isnull=True):
        Rolle.objects.create(gruppe=gruppe, zwei_faktor_pflicht=False)


